/* The tables the engine reads against the file they were generated from.
 *
 * The engine indexes the named arrays in tables_data.h, generated by
 * tools/mktables.py from data/tables.bin, which `make tables` re-extracts from
 * the ROM. So the file is no longer the only copy and the two can drift - a
 * regenerated binary with a stale tables_data.c would be silent. This parses
 * the file and compares every entry against what is compiled in.
 */
#include <stdio.h>
#include <string.h>

#include "../src/core/tables.h"
#include "../src/core/tables_data.h"

static int fails;

static void cmp32(const char *what, const void *a, const void *b, int n)
{
    const int32_t *x = a, *y = b;
    int i;

    if (!x || !y) {
        fprintf(stderr, "FAIL: %s is missing from one of them\n", what);
        fails++;
        return;
    }
    for (i = 0; i < n; i++)
        if (x[i] != y[i]) {
            fprintf(stderr, "FAIL: %s[%d]: file %d, built in %d\n", what, i,
                    x[i], y[i]);
            fails++;
            return;
        }
}

static void cmp16(const char *what, const int16_t *x, const int16_t *y, int n)
{
    int i;

    for (i = 0; i < n; i++)
        if (x[i] != y[i]) {
            fprintf(stderr, "FAIL: %s[%d]: file %d, built in %d\n", what, i,
                    x[i], y[i]);
            fails++;
            return;
        }
}

int main(void)
{
    static ds10_table_set f;
    int checked = 0;

    if (ds10_tables_load(&f, "data/tables.bin") != 0) {
        fprintf(stderr, "cannot read data/tables.bin\n");
        return 1;
    }

#define C32(field, name, n) do { cmp32(#name, f.field, ds10_tbl_##name, (n)); \
                                 checked += (n); } while (0)
#define C16(field, name, n) do { cmp16(#name, f.field, ds10_tbl_##name, (n)); \
                                 checked += (n); } while (0)
    C32(t.env_rate, env_rate, 128);
    C32(t.lfo_bpm, lfo_bpm, 16);
    C32(t.lfo_free, lfo_free, 128);
    C32(t.porta, porta, 128);
    C32(t.peak, peak, 128);
    C32(t.pitch, pitch, 130);
    C32(t.depth, depth, 128);
    C16(t.mod_a, mod_a, 128);
    C16(t.mod_b, mod_b, 128);
    C32(t.coef, coef, 152);
    C32(fx.lfo_phase_off, fx_lfo_phase, 3);
    C16(fx.flanger_fb, fx_flanger_fb, 128);
    C16(fx.depth, fx_depth, 128);
    C32(fx.delay_div, fx_delay_div, 12);
    C32(fx.lfo_rate, fx_lfo_rate, 128);
    C32(drum_pitch, drum_pitch, 128);
    C16(sincos, sincos, 0x2000);
    C32(voice_init, voice_init, DS10_VOICE_STATE_FIELDS);
    C32(mixer_init, mixer_init, 21);
    C32(fx_init, fx_init, 40);
    C32(knob_min, knob_min, 31);
    C32(knob_range, knob_range, 31);
#undef C32
#undef C16

    if (fails) {
        fprintf(stderr, "FAIL: %d tables differ - regenerate with "
                        "tools/mktables.py\n", fails);
        return 1;
    }
    printf("PASS: %d entries over 22 tables, built in matches the file\n",
           checked);
    return 0;
}
